/**
 * 파일명   : useAppList.js
 * 파일기능 : 앱 리스트 조회 공통 로직 (스토리지 기반)
 * 작성자   : 자동 생성
 */

import { ref, onMounted, onUnmounted } from 'vue'
import { bus, BUS_EVENT } from '@/utils/eventBus'
import { commonStorage } from '@/storage/commonStorage'
import { STORAGE_KEYS } from '@/storage/storageKey'

const getFormattedAppList = (list = []) => {
    return list.map((app, idx) => {
        const appId = app?.app_id || ''
        const prjId = app?.project_id || ''
        const appName = app?.name || ''
        const status = String(app?.knowledge_info?.status) ?? ''

        return {
            id: appId || `app-${idx}`,
            label: app?.name ?? '',
            name: app?.name ?? '',
            appId,
            prjId,
            appName,
            status,
            favorite: app?.favorite || false,
            useCnt: app?.use_cnt || 0,
            _raw: app,
        }
    }).filter((x) => x.appId && x.label)
}

/**
 * 앱 리스트 조회 (상위 N 개 - 스토리지 기반)
 * @param {number} limit - 가져올 개수 (기본값: 5)
 * @returns {Array} 앱 리스트
 */
export const fetchTopApps = (limit = 5) => {
    const allApps = commonStorage.get(STORAGE_KEYS.SIDEMENU_APP_LIST) || []
    return getFormattedAppList(allApps).slice(0, limit)
}

/**
 * 앱 리스트 조회 (reactive - 스토리지 기반)
 * @param {number} limit - 가져올 개수 (기본값: 5)
 * @returns {Object} { appList, fetch }
 */
export const useAppList = (limit = 5) => {
    const appList = ref([])

    const updateList = () => {
        const allApps = commonStorage.get(STORAGE_KEYS.SIDEMENU_APP_LIST) || []
        appList.value = getFormattedAppList(allApps).slice(0, limit)
    }

    // 사이드메뉴 재조회 시 자동 업데이트
    const handleRefresh = () => {
        updateList()
    }

    onMounted(() => {
        updateList()
        bus.on(BUS_EVENT.SIDEMENU_REFRESH, handleRefresh)
    })

    onUnmounted(() => {
        bus.off(BUS_EVENT.SIDEMENU_REFRESH, handleRefresh)
    })

    return {
        appList,
        fetch: updateList,
    }
}
